import { Citation } from '@tale-ui/react/citation';

const sources = [
  {
    id: 'aria-apg',
    title: 'WAI-ARIA Authoring Practices Guide',
    href: '/WAI/ARIA/apg/',
    publisher: 'W3C',
  },
] as const;

export function ResearchNote() {
  return (
    <Citation.Root id="research-note" sources={sources} baseUrl="https://www.w3.org/">
      Use native semantics<Citation.Reference sourceId="aria-apg" /> and established patterns<Citation.Reference sourceId="aria-apg" />.
      <Citation.List />
    </Citation.Root>
  );
}
